fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Pre-allocate the column vector with the correct capacity
    let mut col = Vec::with_capacity(n);
    
    // Iterate through each row and extract the j-th element
    for i in 0..n {
        col.push(input[i][j]);
    }
    
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Pre-allocate the result matrix with m rows
    let mut result = Vec::with_capacity(m);
    
    // For each column j in the original matrix, create a new row in the result
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    
    result
}